==> findPosition.m <==
function [xpos, ypos] = findPosition(taxis, obj, nTrials, view, feat, alignEv)

traj = obj.traj{view};

featix = findDLCFeatIndex(obj.traj,view,{feat});

xpos = nan(numel(taxis),nTrials);
ypos = nan(numel(taxis),nTrials);

vidshift = findVideoOffset(obj);
% vidshift = 1;

for i = 1:nTrials % for each trial

    trix = i;

    % check if video data for trial is good, skip if not
    if isfield(traj(trix),'NdroppedFrames')
        if isnan(traj(trix).NdroppedFrames )
            continue;
        end
    end

    % check if frameTimes exists, if not, create it
    if ~isfield(traj(trix),'frameTimes')
        traj(trix).frameTimes = (1:size(traj(trix).ts,1)) ./ 400;
    end

    % get feat trajs for valid trials
    if ~isnan(traj(trix).frameTimes)
        ts = traj(trix).ts(:,1:2,featix);
        % if tongue, don't smooth
        if ~contains(feat,'tongue')
            ts = mySmooth(ts, 1, 'reflect');
        end
        % linear interpolation of frameTimes to taxis
        tsinterp = interp1(traj(trix).frameTimes-vidshift-obj.bp.ev.(alignEv)(trix), ts, taxis);
    end

    xpos(:,i) = tsinterp(:,1);
    ypos(:,i) = tsinterp(:,2);



    % fill missing values for all features except tongue
    if ~contains(feat,'tongue')
        xpos(:,i) = fillmissing(xpos(:,i),'nearest');
        ypos(:,i) = fillmissing(ypos(:,i),'nearest');
    end

end


end  % findPosition

==> findVelocity.m <==
function [xvel, yvel] = findVelocity(xpos, ypos, feat)


for i = 1:size(xpos,2) % for each trial
    tsinterp = [xpos(:,i) ypos(:,i)];
    basederiv = median(diff(tsinterp),'omitnan');

    % find the difference between the feat velocity and the
    % baseline feature velocity (NOT FOR TONGUE)
    xvel(:,i) = gradient(tsinterp(:,1));
    yvel(:,i) = gradient(tsinterp(:,2));
    if ~contains(feat,'tongue') %|| strcmp(traj(trix).featNames{feat},'nose')
        xvel(:,i) = xvel(:,i) - basederiv(1);
        yvel(:,i) = yvel(:,i) - basederiv(1);
    end

    % fill missing values for all features
    if ~contains(feat,'tongue')
        xvel(:,i) = fillmissing(xvel(:,i),'nearest');
        yvel(:,i) = fillmissing(yvel(:,i),'nearest');
    else
        tempx = xvel(:,i);
        tempx(isnan(tempx)) = 0; % set tongue velocity to 0 if not visible
        xvel(:,i) = tempx;
        tempy = yvel(:,i);
        tempy(isnan(tempy)) = 0; % set tonge velocity to 0 if not visible
        yvel(:,i) = tempy;
    end
end


end  % findVelocity






==> getKinematics.m <==
function kin = getKinematics(obj,me,params)

% ----------------------------------------------
% -- Check if obj already has kin --
% ----------------------------------------------
if isfield(obj,'kin')
    if isfield(params,'reload_kin')
        if params.reload_kin
            % get kinematics
        else
            return % kin = obj.kin
        end
    end
    return % kin = obj.kin
else
    % get kinematics
end


% ----------------------------------------------
% -- Kinematics --
% (xdisp,ydisp,xvel,yvel) for each dlc feature
% ----------------------------------------------
[kin.dat,kin.featLeg,kin.nans] = getKinematicsFromVideo(obj,params);

% ----------------------------------------------
% -- Tongue angle and length --
% ----------------------------------------------
if ismember('tongue',params.traj_features{1})
    [ang,len] = getLickAngleAndLength(kin.featLeg,kin.dat,kin.nans);
    kin.featLeg{end+1} = 'tongue_angle';
    kin.featLeg{end+1} = 'tongue_length';

    kin.dat(:,:,end+1) = ang;
    kin.dat(:,:,end+1) = len;
end

% ----------------------------------------------
% -- Motion energy --
% ----------------------------------------------
kin.featLeg{end+1} = 'motion_energy';

kin.dat(:,:,end+1) = me.data;

% ----------------------------------------------
% -- Standardize kinematics --
% ----------------------------------------------
for featix = 1:size(kin.dat,3)
    temp = kin.dat(:,:,featix);
    temp2 = temp(:);
    kin.dat_std(:,:,featix) = (temp - mean(temp2,'omitnan')) ./ std(temp2,'omitnan'); 
end

% ----------------------------------------------
% -- DIMENSIONALITY REDUCTION --
% ----------------------------------------------
% many of the video features will be highly correlated, so we will perform PCA/FA
% on the matrix of features to reduce the dimensionality to a set of factors that
% best explain the movement captured by the video recordings
kin.dat_reduced = reduceDimensionVideoFeatures(kin.dat,params.feat_varToExplain);

end


==> getKinematicsFromVideo.m <==
function [kin,featLeg,nans] = getKinematicsFromVideo(obj,params)

% ----------------------------------------------
% -- parameters --
% ----------------------------------------------
NvarsPerFeat = 4; % (xdisp,ydisp,xvel,yvel)

feats = params.traj_features; % features to extract kinematics for

taxis = obj.time + params.advance_movement; % time axis to align to

nTrials = obj.bp.Ntrials;

% ----------------------------------------------
% -- get kinematics --
% ----------------------------------------------

xpos = cell(2,1); % one entry for each view
ypos = cell(2,1);

xvel = cell(2,1);
yvel = cell(2,1);

for viewix = 1:numel(feats) % loop through cam0 and cam1
    xpos{viewix} = nan(numel(obj.time),nTrials);
    ypos{viewix} = nan(numel(obj.time),nTrials);
    xvel{viewix} = nan(numel(obj.time),nTrials);
    yvel{viewix} = nan(numel(obj.time),nTrials);
    for featix = 1:numel(feats{viewix}) % loop through number of features for current cam
        feat = feats{viewix}{featix};

        [xpos{viewix}(:,:,featix), ypos{viewix}(:,:,featix)] = findPosition(taxis, obj, nTrials, viewix, feat, params.alignEvent);
        [xvel{viewix}(:,:,featix), yvel{viewix}(:,:,featix)] = findVelocity(xpos{viewix}(:,:,featix), ypos{viewix}(:,:,featix), feat);
    end
end
[xpos, ypos, nans] = setTongueBaselinePosition(xpos,ypos,feats,nTrials);



% compute displacement from origin from x/y pos for each feature

featMat = cell(2,1);
viewNum = cell(2,1);
for viewix = 1:numel(feats) % loop through cam0 and cam1
    featMat{viewix} = nan(size(xpos{viewix}, 1), size(xpos{viewix}, 2), size(xpos{viewix}, 3).*NvarsPerFeat);
    for featix = 1:numel(feats{viewix}) % loop through number of features for current cam
        tempx = xpos{viewix}(:,:,featix);
        tempy = ypos{viewix}(:,:,featix);

        %         featDisp{viewix}(:,:,featix) = sqrt((tempx.^2 + tempy.^2);
        featMat{viewix}(:,:,(featix*NvarsPerFeat)-3) = tempx;
        featMat{viewix}(:,:,featix*NvarsPerFeat-2) = tempy;
        featMat{viewix}(:,:,featix*NvarsPerFeat-1) = xvel{viewix}(:, :, featix);
        featMat{viewix}(:,:,featix*NvarsPerFeat) = yvel{viewix}(:, :, featix);
        viewNum{viewix}(featix) = viewix;
    end
end

% concatenate features into one big matrix of size (time,features*2,trials)
% (displacement + xvel + yvel)

kin = cat(3, featMat{:});
v = cat(2, viewNum{:});
% kin(1:5, :, :) = kin(1:5, :, :).*0; % remove any smoothing artifacts at beginning of trials

allfeats = cat(2, feats{:});
featLeg = cell(size(kin, 3), 1);
for i = 1:numel(allfeats)
    featLeg{i*NvarsPerFeat-3} = [allfeats{i} '_xdisp_view' num2str(v(i))];
    featLeg{i*NvarsPerFeat-2} = [allfeats{i} '_ydisp_view' num2str(v(i))];
    featLeg{i*NvarsPerFeat-1} = [allfeats{i} '_xvel_view' num2str(v(i))];
    featLeg{i*NvarsPerFeat} = [allfeats{i} '_yvel_view' num2str(v(i))];
end


end

%% Helper functions

function [xpos, ypos, nans] = setTongueBaselinePosition(xpos,ypos,feats,nTrials)
% set nans in tongue x/y pos to a baseline position
% baseline position = mean initial tongue position for each lick across the
% entire session
views = [1 2];
ct = 1;
nans.data = cell(20,1);
for v = 1:numel(views)
    view = views(v);
    [~,featix] = patternMatchCellArray(feats{view}',{'tongue'},'all');
    featix = find(featix);
    for f = 1:numel(featix)
        feat = featix(f);
        start.x = [];
        start.y = [];
        nans.data{ct} = cell(nTrials,1);
        nans.feat{ct} = feats{view}{feat};
        for trix = 1:nTrials
            x = squeeze(xpos{view}(:,trix,feat));
            y = squeeze(ypos{view}(:,trix,feat));
            vis.mask = logical(sum(~isnan(x),2)); % just need either visibile in x or y

            istart = ZeroOnesCount(vis.mask);


            xstart = x(istart,:);
            ystart = y(istart,:);

            start.x = [start.x ; xstart];
            start.y = [start.y ; ystart];

            % keep track of nan indices to use for tongue angle calculation
            [istart, iend] = ZeroOnesCount(~vis.mask);
            for i = 1:numel(istart)
                nans.data{ct}{trix} = [nans.data{ct}{trix} ; (istart(i):iend(i))'];
            end
        end

        mux = nanmean(nanmean(start.x,2));
        muy = nanmean(nanmean(start.y,2));

        tempx = xpos{view}(:,:,feat);
        tempx(isnan(tempx)) = mux;
        xpos{view}(:,:,feat) = tempx;
        tempy = ypos{view}(:,:,feat);
        tempy(isnan(tempy)) = muy;
        ypos{view}(:,:,feat) = tempy;

        ct = ct + 1;

    end
end

nans.data = nans.data(~cell2mat(cellfun(@isempty, nans.data,'Uni',0))); % nans{feature}{


% view = 2;
% [~,featix] = patternMatchCellArray(feats{view}',{'tongue'},'all');
% figure;
% for trix = 1:nTrials
%     x = squeeze(xpos{view}(:,trix,featix));
%     y = squeeze(ypos{view}(:,trix,featix));
%     plot(x,'Color',[0 0 0],'LineWidth',2); hold on;
%     plot(y,'Color',[0.6 0.6 0.6],'LineWidth',2)
%     pause
%     clf
% end


end


==> getLickAngleAndLength.m <==
function [ang,len] = getLickAngleAndLength(featLeg,kin,nans)

[~,ix1] = patternMatchCellArray(featLeg,{'top_tongue_xdisp_view2'},'all');
t1x = kin(:, :, ix1);
t1x = setNans(t1x,'top_tongue',nans);

[~,ix2] = patternMatchCellArray(featLeg,{'topleft_tongue_xdisp_view2'},'all');
t2x = kin(:, :, ix2);
t2x = setNans(t2x,'topleft_tongue',nans);

[~,ix1] = patternMatchCellArray(featLeg,{'top_tongue_ydisp_view2'},'all');
t1y = kin(:, :, ix1);
t1y = setNans(t1y,'top_tongue',nans);


[~,ix2] = patternMatchCellArray(featLeg,{'topleft_tongue_ydisp_view2'},'all');
t2y = kin(:, :, ix2);
t2y = setNans(t2y,'topleft_tongue',nans);

[~,ix1] = patternMatchCellArray(featLeg,{'bottom_tongue_xdisp_view2'},'all');
t3x = kin(:, :, ix1);
t3x = setNans(t3x,'bottom_tongue',nans);

[~,ix2] = patternMatchCellArray(featLeg,{'bottomleft_tongue_xdisp_view2'},'all');
t4x = kin(:, :, ix2);
t4x = setNans(t4x,'bottomleft_tongue',nans);

[~,ix1] = patternMatchCellArray(featLeg,{'bottom_tongue_ydisp_view2'},'all');
t3y = kin(:, :, ix1);
t3y = setNans(t3y,'bottom_tongue',nans);

[~,ix2] = patternMatchCellArray(featLeg,{'bottomleft_tongue_ydisp_view2'},'all');
t4y = kin(:, :, ix2);
t4y = setNans(t4y,'bottomleft_tongue',nans);

[~,ix1] = patternMatchCellArray(featLeg,{'jaw_xdisp_view2'},'all');
[~,ix2] = patternMatchCellArray(featLeg,{'jaw_ydisp_view2'},'all');
jx = kin(:, :, ix1);
jy = kin(:, :, ix2);



% tongue_tip_x = 0.5.*(t1x+t2x);
% tongue_tip_y = 0.5.*(t1y+t2y);
tongue_tip_x = 0.5.*(t1x+t3x);
tongue_tip_y = 0.5.*(t1y+t3y);

tongue_base_x = 0.5.*(t2x+t4x);
tongue_base_y = 0.5.*(t2y+t4y);

dx = (tongue_tip_x-jx);
dy = (tongue_tip_y-jy);
ang = atan(dy./dx);
ang(dx<0 & dy>0) = ang(dx<0 & dy>0) + pi;     %Correction for the quadrant that the angle lies in
ang(dx<0 & dy<0) = ang(dx<0 & dy<0) - pi;
len = sqrt(dx.^2 + dy.^2);


end


%% Helper functions

function dat = setNans(dat,feat,nans)

nanfeatix = contains(nans.feat,feat);
nandat = nans.data{nanfeatix};
for trix = 1:size(dat,2)
    dat(nandat{trix},trix) = nan;
end

end

