            [istart, iend] = ZeroOnesCount(~vis.mask);
            for i = 1:numel(istart)
                nans.data{ct}{trix} = [nans.data{ct}{trix} ; (istart(i):iend(i))'];
            end
        end

        mux = nanmean(nanmean(start.x,2));
        muy = nanmean(nanmean(start.y,2));

