% Deletes all of the 'Garbage' clusters from Neuropixels recordings
function obj = deleteGarbageClu(obj)
numprobes = size(obj.clu,2);                    % Get the number of probes in the data object
for i = 1:numprobes                             % For each probe...
    currprobe = i;
    numclu = size(obj.clu{currprobe},2);        % Get the number of clusters recorded from that probe
    touse = true(1,numclu);                     % Make a mask of logical values for each cluster (default is true--to keep the cluster)
    for cc = 1:numclu                           % For each cluster...
        qual = obj.clu{currprobe}(cc).quality;  % Get the cluster quality
        if contains(qual,'garbage')             % If the cluster's quality label is 'garbage'
            touse(cc) = 0;                      % Set the logical value for this cluster to be false (aka will not use this cluster)
        end
    end
    obj.clu{currprobe} = obj.clu{currprobe}(touse);     % Take only the clusters from indices that have a 'touse' value as true (aka does not have a garbage label)
end


end====
====
% find offset between neural data file start and video file start
function vidshift = findVideoOffset(obj)
bitStart = mode(obj.bp.ev.bitStart);
vidFileOffset = mode(obj.sglx.bitcode.bitstart) / obj.sglx.fs;
vidshift = vidFileOffset - bitStart; % (s)
end==== getOutcome
function outcome = getOutcome(obj)

% get choice on previous trial

outcome = cell(numel(obj),1);

for sessix = 1:numel(obj)
    outcome{sessix} = obj(sessix).bp.hit; 
    ignore = logical(obj(sessix).bp.no);
    outcome{sessix}(ignore) = nan;
end


end==== firstLickTime
function firstLT = firstLickTime(obj)

% get time of first lickport contact, relative to go cue, on each trial

firstLT = cell(numel(obj),1);

for sessix = 1:numel(obj)
    for trix = 1:obj(sessix).bp.Ntrials
        gc = obj(sessix).bp.ev.goCue(trix);

        lickR = obj(sessix).bp.ev.lickR{trix};
        lickL = obj(sessix).bp.ev.lickL{trix};
        licktimes = sort([lickR lickL]) - gc;
        licktimes(licktimes <= 0) = []; % only keep licks that occurred after go cue

        if ~isempty(licktimes)
            firstLT{sessix}(trix) = licktimes(1);
        else
            firstLT{sessix}(trix) = nan; % no licks on this trial
        end
    end

end

if numel(firstLT) == 1
    firstLT = firstLT{1}; % just return an array rather than a cell if one session
end


end

