%   'zeropad' - pad N zeros across 0 index
%   'none'    - don't handle boundary conditions

% returns:
% - out: filtered data, same size as x
% - kernsd: std dev of gaussian kernel

% % example usage:
% x = 5*sin(1:0.01:100)';
% y = x + randn(size(x));
% N = 51;
% out = mySmooth(y,N,'reflect');
% 
% figure;
% subplot(3,1,1); plot(x);
% xlim([-100 200])
% subplot(3,1,2); plot(y)
% xlim([-100 200])
% subplot(3,1,3); plot(out); %hold on; plot(out,'.','MarkerSize',6)
% xlim([-100 200])


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

if N == 0 || N == 1 % no smoothing
    out = x;
    kernsd = 0;
    return
end

if isrow(x) % if 1-d time series, ensure column vector
    x = x';
end

if nargin > 2
    % handle a boundary condition
    bctype = varargin{1};
    if strcmpi(bctype,'reflect')
        x_filt = cat(1,x(1:N,:),x);
        trim = N + 1;
    elseif strcmpi(bctype,'zeropad')
        x_filt = cat(1,zeros(N,size(x,2)),x);
        trim = N + 1;
    elseif strcmpi(bctype,'none')
        x_filt = x;
        trim = 1;
    else
        warning('invalid boundary condition type - regular smoothing');
        x_filt = x;
        trim = 1;
    end
else
    % no bc handling
    x_filt = x;
    trim = 1;
end



Ncol = size(x_filt, 2);
Nel = size(x_filt, 1);

kern = gausswin(N);
kernsd = std(1:N);


kern(1:floor(numel(kern)/2)) = 0; %causal
kern = kern./sum(kern);

out = zeros(Nel, Ncol);
for j = 1:Ncol
    out(:, j) = conv(x_filt(:, j), kern, 'same');
end
out = out(trim:end,:);

end====
function prevchoice = getPrevChoice(obj)

% get choice on previous trial

prevchoice = cell(numel(obj),1);

for sessix = 1:numel(obj)
    prevchoice{sessix} = nan;

    choice = double((obj(sessix).bp.R&obj(sessix).bp.hit) | (obj(sessix).bp.L&obj(sessix).bp.miss));

    ignore = logical(obj(sessix).bp.no);

    choice(ignore) = nan;

    prevchoice{sessix} = [prevchoice{sessix} ; choice(1:end-1)];

end


