import numpy as np
import h5py


def s2s(d):
    """uint16 char array -> python str"""
    a = np.array(d).ravel()
    return ''.join(chr(int(c)) for c in a)


class Obj:
    def __init__(self, path):
        self.path = path
        self.f = h5py.File(path, 'r')
        self.o = self.f['obj']

    def close(self):
        self.f.close()

    # --- helpers -------------------------------------------------
    def deref(self, ref):
        return self.f[ref]

    def cellstr(self, ref):
        arr = np.array(self.f[ref]).ravel()
        return [s2s(self.f[r]) for r in arr]

    def bp(self, name):
        """1-D bpod field, length Ntrials"""
        return np.array(self.o['bp'][name]).ravel()

    def ev(self, name):
        return np.array(self.o['bp']['ev'][name]).ravel()

    def ev_cell(self, name):
        """lickL / lickR : cell array of lick times per trial"""
        refs = np.array(self.o['bp']['ev'][name]).ravel()
        out = []
        for r in refs:
            d = self.f[r]
            a = np.array(d).ravel()
            if a.dtype != np.float64 or d.shape == (2,):
                # empty cell is stored as a uint64 (2,) placeholder
                a = np.zeros(0)
            out.append(np.asarray(a, dtype=float))
        return out

