    def Ntrials(self):
        return int(np.array(self.o['bp']['Ntrials']).ravel()[0])

    # --- metadata ------------------------------------------------
    @property
    def anm(self):
        return s2s(self.o['ex']['anm'])

    @property
    def date(self):
        return s2s(self.o['ex']['day'])

    def probe_loc(self, prb):
        """prb is 1-based"""
        try:
            return s2s(self.f[self.o['ex']['probe']['loc'][prb - 1, 0]]).strip()
