        return out

    @property
    def Ntrials(self):
        return int(np.array(self.o['bp']['Ntrials']).ravel()[0])

    # --- metadata ------------------------------------------------
    @property
    def anm(self):
        return s2s(self.o['ex']['anm'])

    @property
    def date(self):
        return s2s(self.o['ex']['day'])

    def probe_loc(self, prb):
        """prb is 1-based"""
        try:
            return s2s(self.f[self.o['ex']['probe']['loc'][prb - 1, 0]]).strip()
        except Exception:
            return ''

    def probe_type(self, prb):
        try:
            return s2s(self.f[self.o['ex']['probe']['type'][prb - 1, 0]]).strip()
        except Exception:
            return ''

    @property
    def nprobes(self):
        return self.o['clu'].shape[0]

    # --- clusters ------------------------------------------------
    def clu_group(self, prb):
        """prb 1-based; returns h5 group or None if probe has no sorted data"""
        ref = self.o['clu'][prb - 1, 0]
        g = self.f[ref]
        if not isinstance(g, h5py.Group):
            return None
        return g

    def qualities(self, prb):
        g = self.clu_group(prb)
        if g is None:
            return []
        q = g['quality']
        out = []
        for i in range(q.shape[0]):
            d = self.f[q[i, 0]]
            try:
                out.append(s2s(d).strip())
            except Exception:
                out.append('')
        return out

    def clu_spikes(self, prb, i):
        """0-based cluster index -> (trialtm, trial) arrays"""
        g = self.clu_group(prb)
        trialtm = np.array(self.f[g['trialtm'][i, 0]]).ravel().astype(np.float64)
        trial = np.array(self.f[g['trial'][i, 0]]).ravel().astype(np.int64)
        return trialtm, trial

    # --- video ---------------------------------------------------
    def featnames(self, view):
        g = self.f[self.o['traj'][view, 0]]
        return self.cellstr(g['featNames'][0, 0])

    def traj_group(self, view):
        return self.f[self.o['traj'][view, 0]]

    def frame_times(self, view, trix):
        g = self.traj_group(view)
        if 'frameTimes' not in g:
            return None
        d = self.f[g['frameTimes'][trix, 0]]
        a = np.array(d).ravel()
        if a.size == 0 or a.dtype != np.float64:
            return None
        return a

    def ts(self, view, trix):
        """(nframes, 3, nfeats) as in MATLAB"""
        g = self.traj_group(view)
        d = self.f[g['ts'][trix, 0]]
        a = np.array(d)  # (nfeats, 3, nframes)
        if a.ndim != 3:
            return None
        return np.transpose(a, (2, 1, 0))

    def ndropped(self, view, trix):
        g = self.traj_group(view)
        if 'NdroppedFrames' not in g:
            return None
        a = np.array(self.f[g['NdroppedFrames'][trix, 0]]).ravel()
        if a.size == 0:
            return None
        return float(a[0])

    def video_offset(self):
        """findVideoOffset.m : mode(sglx.bitcode.bitstart)/fs - mode(bp.ev.bitStart)"""
        from scipy import stats
        fs = float(np.array(self.o['sglx']['fs']).ravel()[0])
        bs = np.array(self.o['sglx']['bitcode']['bitstart']).ravel()
        bitStart = np.array(self.o['bp']['ev']['bitStart']).ravel()
        m1 = stats.mode(bs, keepdims=False).mode
        m2 = stats.mode(bitStart[~np.isnan(bitStart)], keepdims=False).mode
        return float(m1) / fs - float(m2)

