import scipy.io as sio,numpy as np,glob,os
for fn in sorted(glob.glob('*/motionEnergy_*.mat')):
    try:
        d=sio.loadmat(fn,struct_as_record=False,squeeze_me=False)
        me=d['me'][0,0]
        fl=me._fieldnames
        dd=me.data
        if 'data' in fl and dd.dtype==object:
            n=dd.size; l0=dd.ravel()[0].shape
        else:
            n=dd.shape; l0=None
        print(os.path.basename(fn), fl, n, l0, me.moveThresh.ravel() if 'moveThresh' in fl else None)
    except Exception as e:
        print(os.path.basename(fn),'ERR',e)
" 2>&1 | head -60

