        self.f = h5py.File(path, 'r')
        self.o = self.f['obj']

    def close(self):
        self.f.close()

    def bp(self, name):
        g = self.o['bp']
        for part in name.split('.'):
            g = g[part]
        return np.array(g).ravel().astype(float)

    def has_bp(self, name):
        g = self.o['bp']
        for part in name.split('.'):
            if part not in g:
                return False
            g = g[part]
        return True

    @property
    def Ntrials(self):
        return int(np.array(self.o['bp']['Ntrials']).ravel()[0])

    def licks(self, side):
        refs = np.array(self.o['bp']['ev']['lick' + side]).ravel()
        out = []
        for r in refs:
            d = self.f[r]
            a = np.array(d)
            if a.dtype != np.float64:
                a = np.zeros(0)
            out.append(np.asarray(a, float).ravel())
        return out

    # clusters
    @property
    def nprobes(self):
        return self.o['clu'].shape[0]

    def _clu(self, prb):
        g = self.f[self.o['clu'][prb - 1, 0]]
        return g if isinstance(g, h5py.Group) else None

    def qualities(self, prb):
        g = self._clu(prb)
        if g is None:
            return []
        q = g['quality']
        out = []
        for i in range(q.shape[0]):
            try:
                out.append(_s2s(self.f[q[i, 0]]).strip().replace('\x00', ''))
            except Exception:
                out.append('')
        return out

    def spikes(self, prb, i):
        g = self._clu(prb)
        tt = np.array(self.f[g['trialtm'][i, 0]]).ravel().astype(np.float64)
        tr = np.array(self.f[g['trial'][i, 0]]).ravel().astype(np.int64)
        return tt, tr

    # video
    def featnames(self, view):
        g = self.f[self.o['traj'][view, 0]]
        fn = g['featNames']
        # struct array: featNames[trial,0] -> cell array of strings
        arr = np.array(self.f[fn[0, 0]]).ravel()
        return [_s2s(self.f[r]) for r in arr]

    def ntraj(self, view):
        return self.f[self.o['traj'][view, 0]]['ts'].shape[0]

    def traj_trial(self, view, trix):
        """returns ts (nframes,3,nfeat), frameTimes (nframes,), ndropped"""
        g = self.f[self.o['traj'][view, 0]]
        try:
            a = np.array(self.f[g['ts'][trix, 0]])
        except Exception:
            return None, None, np.nan
        if a.ndim != 3:
            return None, None, np.nan
        ts = np.transpose(a, (2, 1, 0))
        ft = None
        if 'frameTimes' in g:
            d = np.array(self.f[g['frameTimes'][trix, 0]])
            if d.dtype == np.float64:
                ft = d.ravel()
        nd = np.nan
        if 'NdroppedFrames' in g:
            d = np.array(self.f[g['NdroppedFrames'][trix, 0]]).ravel()
            if d.size and d.dtype == np.float64:
                nd = float(d[0])
        return ts, ft, nd

    def sglx_fs(self):
        return float(np.array(self.o['sglx']['fs']).ravel()[0])

    def sglx_bitstart(self):
        return np.array(self.o['sglx']['bitcode']['bitstart']).ravel().astype(float)

    def probe_loc(self, prb):
        try:
            return _s2s(self.f[self.o['ex']['probe']['loc'][prb - 1, 0]]).strip().replace('\x00', '')
        except Exception:
            return ''


class _V7Session:
    fmt = 'v7'

    def __init__(self, path):
        self.path = path
        d = sio.loadmat(path, struct_as_record=False, squeeze_me=False)
        self.o = d['obj'][0, 0]
        self._bp = self.o.bp[0, 0]

    def close(self):
        self.o = None
        self._bp = None

    def bp(self, name):
        g = self._bp
        parts = name.split('.')
        for p in parts[:-1]:
            g = getattr(g, p)[0, 0]
        return np.array(getattr(g, parts[-1])).ravel().astype(float)

    def has_bp(self, name):
        g = self._bp
        parts = name.split('.')
        for p in parts[:-1]:
            if not hasattr(g, p):
                return False
            g = getattr(g, p)[0, 0]
        return hasattr(g, parts[-1])

    @property
    def Ntrials(self):
        return int(np.array(self._bp.Ntrials).ravel()[0])

    def licks(self, side):
        c = getattr(self._bp.ev[0, 0], 'lick' + side)
        out = []
        for x in c.ravel():
            a = np.asarray(x, float).ravel()
            out.append(a)
        return out

    @property
    def nprobes(self):
        return self.o.clu.size

    def _clu(self, prb):
        c = self.o.clu.ravel()[prb - 1]
        return c.ravel() if c.size else None

    def qualities(self, prb):
        c = self._clu(prb)
        if c is None:
            return []
        return [_s2s(x.quality).strip().replace('\x00', '') for x in c]

    def spikes(self, prb, i):
        c = self._clu(prb)
        return (np.asarray(c[i].trialtm, float).ravel(),
                np.asarray(c[i].trial, np.int64).ravel())

    def featnames(self, view):
        t = self.o.traj.ravel()[view].ravel()
        return [_s2s(x) for x in np.array(t[0].featNames).ravel()]

    def ntraj(self, view):
        return self.o.traj.ravel()[view].ravel().size

    def traj_trial(self, view, trix):
        t = self.o.traj.ravel()[view].ravel()[trix]
        ts = np.asarray(t.ts, float)
        if ts.ndim != 3:
            return None, None, np.nan
        ft = np.asarray(t.frameTimes, float).ravel() if hasattr(t, 'frameTimes') else None
        if ft is not None and ft.size == 0:
            ft = None
        nd = np.nan
        if hasattr(t, 'NdroppedFrames'):
            a = np.asarray(t.NdroppedFrames, float).ravel()
            if a.size:
                nd = float(a[0])
        return ts, ft, nd

    def sglx_fs(self):
        return float(np.array(self.o.sglx[0, 0].fs).ravel()[0])

    def sglx_bitstart(self):
        return np.array(self.o.sglx[0, 0].bitcode[0, 0].bitstart).ravel().astype(float)

    def probe_loc(self, prb):
        try:
            pr = self.o.ex[0, 0].probe.ravel()[prb - 1]
            return _s2s(pr.loc).strip().replace('\x00', '')
        except Exception:
            return ''


def open_session(path):
    with open(path, 'rb') as fh:
        head = fh.read(128)
    if b'MATLAB 7.3' in head:
        return _H5Session(path)
    return _V7Session(path)

