import numpy as np, os
from dataio_draft import open_session
from count_units import FIXED,RAND,DIR
for tag,sess in [('fixed',FIXED),('rand',RAND)]:
    for anm,date,probes in sess:
        fn=os.path.join(DIR[tag],f'data_structure_{anm}_{date}.mat')
        o=open_session(fn)
